def digest(data):
    return hashlib.sha256(data.replace(b'\r\n',b'\n')).hexdigest()

def main():
    root=Path.cwd().resolve()
    if not (root/'pubspec.yaml').is_file() or not (root/'lib').is_dir():
        print('Откройте терминал в папке moy_prihod, где находится pubspec.yaml.');return 1
    pending=[];conflicts=[]
    for rel,item in CHANGES.items():
        target=root/rel
        if not target.is_file() or target.is_symlink() or not target.resolve().is_relative_to(root):
            conflicts.append(rel);continue
        data=target.read_bytes();checksum=digest(data)
        if checksum==item['after']:continue
        if checksum!=item['before']:
            conflicts.append(rel);continue
        replacement=base64.b64decode(item['data'])
        if digest(replacement)!=item['after']:raise ValueError('Damaged patch payload')
        pending.append((rel,target,data,replacement))
    if conflicts:
        print('Изменения не внесены: эти файлы отличаются от исходного архива:')
        print('\n'.join(conflicts));print('Пришлите этот вывод, чтобы сохранить ваши изменения.');return 1
    if not pending:
        print('Исправления уже установлены. Выполните flutter analyze.');return 0
    backup=root/'fix_backups'/datetime.now().strftime('%Y%m%d_%H%M%S_%f')
    for rel,target,data,replacement in pending:
        saved=backup/rel;saved.parent.mkdir(parents=True,exist_ok=True);saved.write_bytes(data)
    written=[]
    try:
        for rel,target,data,replacement in pending:
            written.append((target,data));target.write_bytes(replacement)
    except Exception:
        for target,data in reversed(written):target.write_bytes(data)
        raise
    print('Исправлено файлов:',len(pending));print('Резервная копия:',backup)
    print('Теперь выполните flutter analyze и пришлите результат.')
    return 0

if __name__=='__main__':
    sys.exit(main())
